<?php use CmuLms\View;$title='Messages';include __DIR__.'/../layout/header.php';?><section class="card"><h1>Messages</h1><form method="post" action="?route=message-send"><?=View::csrfField()?><select name="recipient_id" required><option value="">Select recipient</option><?php foreach($users as $x):?><option value="<?=(int)$x['id']?>"><?=View::e($x['name'])?> · <?=View::e($x['id_number'])?></option><?php endforeach;?></select><textarea name="body" placeholder="Message" required></textarea><button>Send message</button></form></section><section class="card"><?php foreach($items as $m):?><article><strong><?=View::e($m['sender_name'])?></strong><p><?=View::e($m['body'])?></p><small><?=View::e($m['created_at'])?></small></article><?php endforeach;?></section><?php include __DIR__.'/../layout/footer.php';?>
